 first=p.calls[0];p.mode='ok';p.get_gate=asyncio.Event();await f.locator('#take-request').click();await expect(f.locator('#state-panel')).to_be_visible();await f.locator('body').evaluate('()=>new Promise(requestAnimationFrame)');p.get_gate.set();await expect(f.locator('#loaded-content')).to_be_visible();await expect(f.locator('#detail')).not_to_be_visible();assert p.calls[-1]==first;assert len(p.calls)==2;await expect(f.locator('[data-request="request-12"]')).to_be_focused();assert abs(await f.locator('body').evaluate('()=>scrollY')-position)<3;assert await f.locator('body').evaluate('()=>document.activeElement.dataset.request')=='request-12';groups.append('explicit retry keeps revision; success restores list position and action')
